  "role": "poète épique grec",
  "idea": "Ses poèmes épiques ont fixé l'image grecque des dieux et des héros, et ont été la base de l'éducation et de la pensée mythique antérieure à la philosophie.",
  "bio": "<p>Homère est le nom que la tradition grecque a donné au poète de l'<em>Iliade</em> et de l'<em>Odyssée</em>, composées probablement au VIIIe siècle av. J.-C. en Ionie. On ne sait presque rien de sûr sur sa vie : plusieurs villes, comme Smyrne ou Chios, se disputaient son berceau, et selon la tradition c'était un aède aveugle. Beaucoup de spécialistes pensent que les poèmes recueillent une longue tradition orale que quelqu'un a mise par écrit ; c'est ce qu'on appelle la question homérique.</p>\n<p>Ses poèmes furent la base de l'éducation grecque : on y apprenait l'<strong>aretè</strong> (l'excellence) du héros et l'on y découvrait les dieux, qui agissent avec des passions humaines et décident du destin des mortels. C'est pourquoi il figure au programme comme exemple de la <strong>pensée mythique</strong>, contre laquelle réagissent les premiers philosophes, et comme cible de la critique de Xénophane.</p>",
  "obras": [
   "Iliade",
   "Odyssée"
  ],
  "anecdota": "<p>Une ancienne légende raconte que, déjà vieux, Homère rencontra dans l'île d'Ios des garçons qui revenaient de la pêche. Il leur demanda ce qu'ils avaient pris et ils répondirent par une énigme : « Ce que nous avons attrapé, nous l'avons laissé ; ce que nous n'avons pas attrapé, nous l'emportons avec nous ». Le poète qui savait tout sur les dieux et les héros ne sut pas la résoudre. La réponse, c'étaient les poux qu'ils s'étaient enlevés, assis sur la plage. Héraclite faisait déjà allusion à cette histoire pour se moquer de ceux qui se fient à la sagesse des poètes : même le plus grand des Grecs s'est laissé tromper par ce qu'il avait sous les yeux.</p>",
  "fuente": "Vie d'Homère attribuée à Hérodote ; Certamen d'Homère et d'Hésiode ; Héraclite, fragment sur Homère et les poux",
